  'ROJO   →  VΩ (termopar +)': { en: 'RED   →  VΩ (thermocouple +)', pt: 'VERMELHO   →  VΩ (termopar +)', ja: '赤   →  VΩ (熱電対 +)', zh: '红   →  VΩ (热电偶 +)', ko: '빨강   →  VΩ (열전대 +)', ru: 'КРАСНЫЙ   →  VΩ (термопара +)' },
  'ROJO   →  VΩ Hz': { en: 'RED   →  VΩ Hz', pt: 'VERMELHO   →  VΩ Hz', ja: '赤   →  VΩ Hz', zh: '红   →  VΩ Hz', ko: '빨강   →  VΩ Hz', ru: 'КРАСНЫЙ   →  undefined' },
