  'Rojo: en VΩ casi siempre.': { en: 'Red: VΩ most of the time.', pt: 'Vermelho: quase sempre em VΩ.', ja: '赤はほとんどの場合 VΩ です。', zh: '红表笔:大多数时候接 VΩ。', ko: '빨강은 대부분 VΩ에 꽂아요.', ru: 'Красный: почти всегда в VΩ.' },
  'SALIDA': { en: 'OUTPUT', pt: 'SAÍDA', ja: '出力', zh: '输出', ko: '출력', ru: 'ВЫХОД' },
  'SIN ENERGÍA': { en: 'NO POWER', pt: 'SEM ENERGIA', ja: '通電なし', zh: '未通电', ko: '전원 꺼짐', ru: 'БЕЗ ПИТАНИЯ' },
  'SONAR': { en: 'SONAR', pt: 'SONAR', ja: 'ソナー', zh: '声呐', ko: '소나', ru: 'СОНАР' },
  'Si sale #, invertiste las puntas.': { en: 'If it shows #, you swapped the probes.', pt: 'Se aparecer #, você inverteu as pontas.', ja: '# と出たら、テストリードが逆です。', zh: '如果显示 #,说明表笔接反了。', ko: '# 라고 나오면 프로브가 반대로 꽂힌 거예요.', ru: 'Если на экране #, вы поменяли щупы местами.' },
  'Siempre SIN energía.': { en: 'Always with NO power.', pt: 'Sempre SEM energia.', ja: '必ず通電していない状態で測ります。', zh: '务必在断电状态下测量。', ko: '항상 전원이 꺼진 상태에서 재요.', ru: 'Только БЕЗ питания.' },
  'TEMPERATURA': { en: 'TEMPERATURE', pt: 'TEMPERATURA', ja: '温度', zh: '温度', ko: '온도', ru: 'ТЕМПЕРАТУРА' },
  'TERMOPAR K': { en: 'K THERMOCOUPLE', pt: 'TERMOPAR K', ja: 'K熱電対', zh: 'K型热电偶', ko: 'K형 열전대', ru: 'ТЕРМОПАРА K' },
