  'Tu multímetro mide': { en: 'Your multimeter measures', pt: 'Seu multímetro mede', ja: 'マルチメーターで測れるもの', zh: '你的万用表可以测量', ko: '멀티미터로 잴 수 있는 것', ru: 'Ваш мультиметр измеряет' },
