  "Más de # s: el flux se acaba": { en: "Over # s: the flux runs out", pt: "Mais de # s: o fluxo acaba", ja: "# 秒以上：フラックスが尽きて", zh: "超过 # 秒：助焊剂耗尽，", ko: "# 초 넘으면: 플럭스가 다 타고", ru: "Дольше # с: флюс выгорает," },
  "y el pad se puede despegar.": { en: "and the pad can peel off.", pt: "e o pad pode descolar.", ja: "パッドがはがれることも。", zh: "焊盘可能会翘起。", ko: "패드가 떨어질 수 있다.", ru: "и площадка может отойти." },
